run-checkpoint-derive.bats:80:@test "RCD-1 drift fixture (D-5.4): cache RUNNING, three COMPLETED markers with APPROVED trailers, ledger completed → COMPLETE; --write makes the cache say so" {
run-checkpoint-derive.bats:101:@test "RCD-2 a stale marker whose trailers name sprint-1 of another cycle (or whose sprint: line names another sprint) is stale_marker, not counted" {
run-checkpoint-derive.bats:122:@test "RCD-3 legacy feedback (no LOA-VERDICT trailer) yields no verdict: the sprint stays incomplete and the file is named in derivation.legacy_feedback" {
run-checkpoint-derive.bats:129:  [ "$(dj '.derivation.legacy_feedback | join(",")')" = "grimoires/loa/a2a/sprint-103/engineer-feedback.md" ]
run-checkpoint-derive.bats:132:  [ "$(jq -r '.derivation.legacy_feedback[0]' "$R/.run/sprint-plan-state.json")" = "grimoires/loa/a2a/sprint-103/engineer-feedback.md" ]
run-checkpoint-derive.bats:135:@test "RCD-4 review and audit APPROVED without a marker is awaiting_marker (counted incomplete); a marker with the ledger row not completed is in_progress" {
run-checkpoint-derive.bats:154:@test "RCD-5 JACKED_OUT is terminal: a cache .state or .status JACKED_OUT, or .completion.merged_sha, stays JACKED_OUT with contradicting files reported as drift" {
run-checkpoint-derive.bats:175:@test "RCD-6 HALTED is sticky: a cache HALTED stays HALTED even when every sprint is complete; a breaker OPEN halts a RUNNING cache" {
run-checkpoint-derive.bats:189:@test "RCD-7 COMPLETE never moves back to RUNNING unless the ledger registers a new incomplete sprint" {
run-checkpoint-derive.bats:207:@test "RCD-8 an incomplete sprint is RUNNING while last_activity is within run_mode.stale_hours (default 12), else INTERRUPTED; the key widens the window" {
run-checkpoint-derive.bats:231:@test "RCD-9 breaker recompute: two -r1 feedback files and a zeroed breaker give cycle_count 2, same_issue 2, no_progress 1; counters are raised, never lowered" {
run-checkpoint-derive.bats:258:@test "RCD-10 three identical changes-required rounds meet the same-issue threshold: the derived breaker trips OPEN (history source derive) and the run derives HALTED" {
run-checkpoint-derive.bats:272:@test "RCD-11 schema tolerance: a file without derived_at, derivation or .status reads fine, gains the fields on --write and keeps its schema_version" {
run-checkpoint-derive.bats:291:@test "RCD-12 run_mode.file_authoritative: false makes --write report-only: the caches stay byte-identical and the report says why" {
run-checkpoint-derive.bats:312:@test "RCD-13 no active cycle or no ledger → exit 4 with a named reason; the cache is untouched" {
run-checkpoint-derive.bats:326:@test "RCD-14 write refreshes the derived cache after its own update; an unparseable cache is reported and never rewritten" {
run-checkpoint-derive.bats:342:@test "RCD-15 impl_commit is the newest non-merge commit since the sprint started that touches a path outside the state set; state-only commits are skipped" {
run-checkpoint-derive.bats:358:@test "RCD-16 the jack-out step in completion-modes.md writes .state (and mirrors .status) on the sprint-plan cache; run-resume derives on drift; the recovery doc reads .state" {
run-checkpoint-derive.bats:368:@test "RCD-17 a ledger row without local_label or timestamps keeps its fields aligned (empty TSV fields do not collapse)" {
run-checkpoint-derive.bats:379:@test "RCD-R1 loa-run-state-surface.sh prints for a derived file exactly what it prints for a hand-written file with the same .state" {
run-checkpoint-derive.bats:400:@test "RCD-R2 run-preflight.sh P6 classifies a derived file as it classifies the same .state by hand (resumable HALTED/INTERRUPTED, in progress RUNNING)" {
run-checkpoint-derive.bats:419:@test "RCD-R3 golden-path.sh: the bug-state detector reads .run/bugs/*/state.json as before, a derived sprint-plan cache beside it changes nothing" {
run-checkpoint-derive.bats:431:@test "RCD-R4 implement-gate.sh over a derived file: derived RUNNING sanctions (one sanctioned_run row); derived COMPLETE under deny is denied; a cache derived 13 h ago is an unknown position" {
run-checkpoint-derive.bats:453:@test "RCD-R5 the /loa Run line reports drift report-only (files say X, cache said Y) and the Gate line prints the effective mode; nothing is written" {
run-checkpoint-record-round.bats:46:@test "RCR-1 a CHANGES_REQUIRED review increments cycle_count.current, sets same_issue {count 1, last_hash} to the SKILL's derived hash, exit 0" {
run-checkpoint-record-round.bats:59:@test "RCR-2 the same hash again counts up; a different finding set resets same_issue to 1 with the new last_hash" {
run-checkpoint-record-round.bats:74:@test "RCR-3 no_progress counts consecutive rounds whose counts are unchanged and resets when they change" {
run-checkpoint-record-round.bats:87:@test "RCR-4 a trip at threshold writes state OPEN, appends one history entry, sets .run/state.json HALTED, prints TRIPPED and exits 10" {
run-checkpoint-record-round.bats:105:@test "RCR-5 the cycle limit, the no-progress threshold and the timeout trip in that documented order" {
run-checkpoint-record-round.bats:122:@test "RCR-6 APPROVED leaves every counter and the run state as they were (exit 0)" {
run-checkpoint-record-round.bats:133:@test "RCR-7 an inconsistent APPROVED trailer counts as findings; a legacy file without a trailer hashes its findings section; a missing breaker file is created from the schema defaults" {
run-checkpoint-record-round.bats:139:  printf '# Review\n\n## Findings\n\n- a legacy finding\n' > "$T/a2a/engineer-feedback.md"
run-checkpoint-record-round.bats:148:@test "RCR-8 usage: a missing feedback file or gate exits 2 and writes nothing" {

